arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ __schema { queryType { fields { name args { name type { kind name ofType { kind name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if f['name'] in ('projects','project'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ', a['name'], t['kind'], t.get('name'), t.get('ofType'))
"

